					body.style.setProperty("background-image", dark
						? "radial-gradient(1100px 560px at 88% -12%, rgba(214, 175, 98, .1), transparent 62%), radial-gradient(900px 520px at -12% 112%, rgba(125, 157, 120, .09), transparent 60%), linear-gradient(158deg, #151b10 0%, #10150a 100%)"
						: "radial-gradient(1100px 560px at 88% -12%, rgba(197, 162, 94, .18), transparent 62%), radial-gradient(900px 520px at -12% 112%, rgba(95, 125, 90, .12), transparent 60%), linear-gradient(158deg, #f6f0de 0%, #efe7cf 55%, #e9dfc0 100%)");
